		max_flow_value+=capacity_arr[t];
		total_cost_value+=capacity_arr[t]*dist_arr[t];
		for (int v=t; v!=s; v=edge_list[prev_edge_idx[v]].u) {
			edge_list[prev_edge_idx[v]].flow+=capacity_arr[t];
			edge_list[prev_edge_idx[v]^1].flow-=capacity_arr[t];
		}
	}
}

